<?php require_once __DIR__.'/config/auth.php'; exigirPerfil(['Administrador','Técnico','Trabalhador']); require_once __DIR__.'/config/conexao.php';
function contar($conn,$sql){$r=$conn->query($sql);return $r?(int)$r->fetch_row()[0]:0;}
$totalClientes=contar($conn,'SELECT COUNT(*) FROM clientes'); $totalEquip=contar($conn,'SELECT COUNT(*) FROM equipamentos'); $totalOS=contar($conn,'SELECT COUNT(*) FROM ordens_servico');
$totalChamados=contar($conn,'SELECT COUNT(*) FROM chamados_cliente');
$chamadosAbertos=contar($conn,"SELECT COUNT(*) FROM chamados_cliente WHERE status IN ('Aberto','Em atendimento','Aguardando cliente')");
$abertas=contar($conn,"SELECT COUNT(*) FROM ordens_servico WHERE status IN ('Aberta','Em andamento','Em atendimento')") + $chamadosAbertos;
$recentes=$conn->query("SELECT os.id,os.data_abertura,os.status,c.nome AS cliente,e.tipo,e.marca,e.modelo FROM ordens_servico os JOIN equipamentos e ON e.id=os.equipamento_id JOIN clientes c ON c.id=e.cliente_id ORDER BY os.data_abertura DESC LIMIT 6");
?>
